function workflow(input,type){if(type==="candidate_mates"){const result=related(input,{limit:20});return{...result,kind:"workflow",data:{type,title:"Candidate mates",notice:`Candidates reuse deterministic algorithm ${ALGORITHM_VERSION}.`,rows:result.data.results||[]}};}if(type==="lexical_witnesses"){const result=related(input,{limit:100}),seen=new Set(),rows=[];for(const row of result.data.results||[])if(!seen.has(row.reference.book)){seen.add(row.reference.book);rows.push(row);if(rows.length===2)break;}return{kind:"workflow",meta:result.meta,data:{type,title:"Two lexical witnesses",notice:"Distinct canonical books are a lexical-independence heuristic, not a theological conclusion.",rows}};}const exact=exactWord(input,500);if(type==="divide_term"){const groups=new Map();for(const match of exact.data.matches){let group=groups.get(match.reference.book);if(!group){group={book:match.reference.book,verseCount:0,occurrenceCount:0,examples:[]};groups.set(match.reference.book,group);}group.verseCount++;group.occurrenceCount+=match.positions.length;if(group.examples.length<3)group.examples.push(match);}return{kind:"workflow",meta:exact.meta,data:{type,title:"Divide term by book",notice:"Groups are observed canonical-book contexts, not inferred senses.",groups:[...groups.values()]}};}return{kind:"workflow",meta:exact.meta,data:{type,title:type==="first_mention_chain"?"First-mention chain":"Gather mentions",notice:"Occurrences are exact normalized-token evidence in canonical order.",rows:type==="first_mention_chain"?exact.data.matches.slice(0,12):exact.data.matches}};}

async function topic(input){const exact=tokenize(input).length===1?exactWord(input,500):exactPhrase(input,500);if(exact.data.total)return{...exact,kind:"topic",data:{status:"exact_kjv",topic:input,exact:exact.data,notice:"The query occurs in the KJV, so no external vocabulary bridge was used."}};const snapshot=await lookupWordNet(input);return{kind:"topic",meta:meta([`topic:${input}`,"bridge:requires_sense_selection"]),data:{status:"requires_sense_selection",topic:input,snapshot,notice:"Choose a dictionary sense before any KJV vocabulary is suggested. WordNet is external evidence, not a biblical definition."}};}
async function lookupWordNet(headword){const normalized=headword.toLowerCase().replaceAll(" ","_");if(!state.wordnet){$("#live-status").textContent="Loading the external WordNet evidence layer";const positions=["noun","verb","adj","adv"];state.wordnet={};await Promise.all(positions.map(async pos=>{const [index,data]=await Promise.all([fetch(`./data/wordnet/index.${pos}`).then(requireOk).then(r=>r.text()),fetch(`./data/wordnet/data.${pos}`).then(requireOk).then(r=>r.text())]);state.wordnet[pos]={index:new Map(index.split(/\r?\n/).filter(line=>line&&!line.startsWith("  ")).map(line=>[line.slice(0,line.indexOf(" ")),line])),data:new Map(data.split(/\r?\n/).filter(Boolean).map(line=>[line.slice(0,8),line]))};}));}const senses=[];for(const [pos,bucket] of Object.entries(state.wordnet)){const line=bucket.index.get(normalized);if(!line)continue;const fields=line.trim().split(/\s+/),count=Number(fields[2]),pointers=Number(fields[3]),offsets=fields.slice(6+pointers,6+pointers+count);for(const offset of offsets){const row=bucket.data.get(offset);if(!row)continue;const divider=row.indexOf("|"),parts=row.slice(0,divider).trim().split(/\s+/),wordCount=parseInt(parts[3],16),synonyms=[];for(let i=0;i<wordCount;i++)synonyms.push(parts[4+i*2].replaceAll("_"," "));senses.push({id:`wn30:${parts[2]}:${offset}`,partOfSpeech:({noun:"noun",verb:"verb",adj:"adjective",adv:"adverb"})[pos],definition:row.slice(divider+1).trim().split(/;\s*"/,1)[0],synonyms});}}if(!senses.length)throw new Error(`Princeton WordNet has no entry for ${headword}.`);return{provider:"Princeton WordNet",providerVersion:"3.0",sourceUrl:WORDNET_SOURCE,license:WORDNET_LICENSE,headword,senses};}

function renderResult(result){$("#result-title").textContent=MODES[state.mode];$("#export-button").disabled=false;$("#live-status").textContent="Search complete";const interpretation=`<div class="interpretation"><span>Parsed deterministically</span><code>${esc(result.meta.queryTrace.join(" · "))}</code><small>${CORPUS_VERSION} / algorithm ${ALGORITHM_VERSION}</small></div>`;let body="";if(result.kind==="reference")body=renderPassage(result.data);else if(result.kind==="exact")body=renderExact(result.data);else if(result.kind==="related")body=renderRelated(result.data);else if(result.kind==="word-family")body=renderWordFamily(result.data);else if(result.kind==="compare")body=renderCompare(result.data);else if(result.kind==="graph")body=renderGraph(result.data);else if(result.kind==="workflow")body=renderWorkflow(result.data);else if(result.kind==="topic")body=renderTopic(result.data);$("#results").innerHTML=interpretation+body;bindTopicActions(result);}
function renderPassage(data){return`<section><div class="section-title"><h3>${esc(data.reference)}</h3><span>${data.requested.length} requested verse${data.requested.length===1?"":"s"}</span></div><ol class="passage-context">${data.context.map(v=>`<li class="${v.requested?"requested":""}"><strong>${esc(v.label)}</strong><p>${esc(v.displayText)}</p></li>`).join("")}</ol></section>`;}
function renderExact(data){const d=data.distribution;return`<section>${d?`<div class="stat-grid"><div class="stat"><span>Verse frequency</span><strong>${d.verseFrequency}</strong></div><div class="stat"><span>Total occurrences</span><strong>${d.totalFrequency}</strong></div><div class="stat"><span>First mention</span><strong>${d.firstMention?esc(label(d.firstMention)):"—"}</strong></div><div class="stat"><span>Last mention</span><strong>${d.lastMention?esc(label(d.lastMention)):"—"}</strong></div></div>`:""}<div class="section-title"><h3>${data.total} matching verses</h3><span>${data.totalOccurrences} occurrences</span></div>${matchTable(data.matches)}</section>`;}
function matchTable(rows){return`<div class="table-wrap"><table><thead><tr><th>Reference</th><th>Exact text</th><th>Positions</th></tr></thead><tbody>${rows.map(m=>`<tr><th>${esc(m.label||label(m.reference))}</th><td>${esc(m.displayText)}</td><td><code>${esc((m.positions||m.startPositions||[]).join(", "))}</code></td></tr>`).join("")}</tbody></table></div>`;}
function renderRelated(data){let rows=data.results;const minimum=Number($("#minimum-score")?.value||0),evidence=$("#evidence")?.value;rows=rows.filter(r=>r.score>=minimum&&(!evidence||r.candidateReasons.includes(evidence)));return`<section><blockquote><strong>${esc(data.source.label)}</strong><p>${esc(data.source.displayText)}</p></blockquote><div class="section-title"><h3>${rows.length} ranked results</h3><span>${data.evaluatedCount??data.candidateCount} of ${data.candidateCount} candidates evaluated${data.prunedCount?` · ${data.prunedCount} pruned`:""}</span></div><div class="table-wrap"><table><thead><tr><th>Rank</th><th>Passage</th><th>Text score</th><th>Evidence</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><th><span class="reference">${esc(r.label)}</span><p>${esc(r.displayText)}</p></th><td><strong>${r.score.toFixed(6)}</strong><small class="score-parts">Word ${r.textualGroups.word} · Letter ${r.textualGroups.letter} · Line ${r.textualGroups.line}<br>Proximity ${r.components.proximity}</small></td><td><details><summary>Why this matched</summary><dl class="evidence-list"><dt>Complete verse identity</dt><dd>${esc(r.identity.level.replaceAll("_"," "))}${r.identity.score?` (${r.identity.score})`:""}</dd><dt>Matched words</dt><dd>${esc(r.matchedTokens.map(t=>`${t.sourceSurface} ↔ ${t.targetSurface} (${t.level.replaceAll("_"," ")})`).join(", ")||"None")}</dd><dt>Near phrases</dt><dd>${esc(r.matchedPhrases.map(p=>`${p.tokens.join(" ")} (gap ${p.totalGap}, × ${p.multiplier})`).join("; ")||"None")}</dd><dt>Morphology</dt><dd>${esc(r.morphologicalMatches.map(m=>`${m.sourceTerm} ↔ ${m.targetTerm}: ${m.kind} [${m.shared.join(", ")}]`).join("; ")||"None")}</dd><dt>Letter pattern</dt><dd>${esc(r.letterPatternMatches.map(m=>`${m.sourceTerm} ↔ ${m.targetTerm}: ${m.kind} “${m.fragment}” (${m.score})`).join("; ")||"None")}</dd><dt>Capitalization</dt><dd>${esc(r.capitalizationEvidence.map(t=>`${t.sourceSurface} ↔ ${t.targetSurface}: ${t.multiplier}`).join(", ")||"None")}</dd><dt>Corpus rarity</dt><dd>${esc(r.rareTokens.map(t=>`${t.token} (${t.corpusFrequency} occurrences, rarity ${round6(t.rarity)}, word evidence ${round6(t.wordEvidence)})`).join(", ")||"None")}</dd><dt>Canonical proximity</dt><dd>${r.components.proximity} · ${esc(Object.entries(r.proximityAxes).map(([key,value])=>`${key} ${value}`).join(" · "))}</dd><dt>Tie-break</dt><dd>${esc(r.tieBreak)}</dd></dl></details></td></tr>`).join("")}</tbody></table></div></section>`;}
function renderWordFamily(data){return`<section><div class="status-card"><strong>Word-family expansion: ${esc(data.query)}</strong><span>${esc(data.notice)}</span></div><div class="section-title"><h3>${data.candidates.length} strongest vocabulary candidates</h3><span>${data.totalDiscovered} retained from ${data.vocabularySize} corpus word forms</span></div><div class="table-wrap"><table><thead><tr><th>Rank</th><th>Candidate</th><th>Relationship</th><th>Strength</th><th>KJV examples</th></tr></thead><tbody>${data.candidates.map((row,index)=>`<tr><td>${index+1}</td><th><span class="reference">${esc(row.targetTerm)}</span><small>${row.documentFrequency} verses</small></th><td>${esc(row.kind.replaceAll("_"," "))}<br><code>${esc(row.sourceTerm)} → ${esc(row.shared.join(", ")||row.targetTerm)} → ${esc(row.targetTerm)}</code></td><td>${row.score.toFixed(6)}</td><td>${row.examples.map(x=>`<strong>${esc(x.label)}</strong> ${esc(x.displayText)}`).join("<br>")||"No occurrence"}</td></tr>`).join("")}</tbody></table></div></section>`;}
function renderCompare(data){return`<section><div class="comparison-grid">${data.passages.map(p=>`<blockquote><strong>${esc(p.label)}</strong><p>${esc(p.displayText)}</p></blockquote>`).join("")}</div><div class="status-card"><strong>Common normalized tokens</strong><span>${esc(data.commonNormalizedTokens.join(", ")||"None")}</span></div><div class="table-wrap"><table><thead><tr><th>Pair</th><th>Score</th><th>Shared phrases</th></tr></thead><tbody>${data.pairs.map(p=>`<tr><th>${esc(p.source)} ↔ ${esc(p.target)}</th><td>${p.explanation.score.toFixed(6)}</td><td>${esc(p.explanation.matchedPhrases.map(x=>x.tokens.join(" ")).join("; ")||"None")}</td></tr>`).join("")}</tbody></table></div></section>`;}
function renderGraph(data){return`<section><blockquote><strong>${esc(data.source.label)}</strong><p>${esc(data.source.displayText)}</p></blockquote><div class="section-title"><h3>${data.nodes.length} evidence nodes</h3><span>${data.edges.length} explained edges</span></div><div class="graph-grid">${data.nodes.map(n=>`<div class="graph-node ${n.type}"><span class="pill">${esc(n.type)}</span><strong>${esc(n.label)}</strong></div>`).join("")}</div><div class="table-wrap"><table><thead><tr><th>From</th><th>To</th><th>Evidence</th></tr></thead><tbody>${data.edges.map(e=>`<tr><td>${esc(e.source)}</td><td>${esc(e.target)}</td><td>${esc(e.type)}${e.term?`: ${esc(e.term)}`:` · ${e.score.toFixed(6)}`}</td></tr>`).join("")}</tbody></table></div></section>`;}
function renderWorkflow(data){if(data.groups)return`<section><div class="status-card">${esc(data.notice)}</div>${data.groups.map(g=>`<details><summary>${esc(g.book)} · ${g.verseCount} verses · ${g.occurrenceCount} occurrences</summary>${g.examples.map(x=>`<blockquote><strong>${esc(x.label)}</strong><p>${esc(x.displayText)}</p></blockquote>`).join("")}</details>`).join("")}</section>`;const rows=data.rows||[];return`<section><div class="status-card">${esc(data.notice)}</div><div class="section-title"><h3>${esc(data.title)}</h3><span>${rows.length} results</span></div>${rows[0]?.score!==undefined?renderRelated({source:{label:"Workflow",displayText:"Deterministic lexical evidence"},candidateCount:rows.length,results:rows}):matchTable(rows)}</section>`;}
function renderTopic(data){if(data.status==="exact_kjv")return`<section><div class="status-card">${esc(data.notice)}</div>${renderExact(data.exact)}</section>`;return`<section><div class="status-card"><strong>External dictionary evidence</strong><span>${esc(data.notice)}</span><small>${esc(data.snapshot.provider)} ${esc(data.snapshot.providerVersion)} · ${esc(data.snapshot.license)}</small></div><fieldset id="sense-list"><legend>Select a sense, or leave all unselected to explore separate reduced-confidence branches</legend>${data.snapshot.senses.map((s,i)=>`<label><input type="radio" name="sense" value="${i}"> <strong>${esc(s.partOfSpeech)}</strong> — ${esc(s.definition)}</label>`).join("<br>")}<button id="use-sense" type="button">Build KJV vocabulary bridges</button></fieldset><div id="topic-next"></div></section>`;}
function bindTopicActions(result){if(result.kind!=="topic"||result.data.status!=="requires_sense_selection")return;$("#use-sense").addEventListener("click",()=>{const checked=document.querySelector('input[name="sense"]:checked'),all=result.data.snapshot.senses,senses=checked?[{sense:all[Number(checked.value)],index:Number(checked.value),confidence:1}]:all.map((sense,index)=>({sense,index,confidence:round6(1/Math.max(2,all.length))})),bridges=[];for(const branch of senses){const synonyms=[...new Set(branch.sense.synonyms.flatMap(value=>tokenize(value)).filter(tokens=>tokens.length===1).map(tokens=>tokens[0].folded))];const best=new Map();for(const synonym of synonyms)for(const relation of candidateWordRelations([synonym],12)){const row={...relation,senseIndex:branch.index,senseId:branch.sense.id,senseDefinition:branch.sense.definition,senseConfidence:branch.confidence,bridgeStrength:round6(relation.score*branch.confidence),synonym};if(!best.has(row.targetTerm)||best.get(row.targetTerm).bridgeStrength<row.bridgeStrength)best.set(row.targetTerm,row);}bridges.push(...[...best.values()].sort((a,b)=>b.bridgeStrength-a.bridgeStrength).slice(0,12));}if(!bridges.length){$("#topic-next").innerHTML='<div class="status-card">No vocabulary bridge candidates were generated.</div>';return;}$("#topic-next").innerHTML=`<div class="status-card">${checked?"One dictionary sense selected.":"No sense selected: each sense remains a separate reduced-confidence branch."} Bridge confidence selects possible KJV vocabulary; it does not alter Scripture-to-Scripture scores.</div>${senses.map(branch=>`<fieldset><legend>${esc(branch.sense.partOfSpeech)} — ${esc(branch.sense.definition)} · confidence ${branch.confidence}</legend>${bridges.filter(row=>row.senseIndex===branch.index).map((row)=>{const index=bridges.indexOf(row);return`<label><input type="checkbox" name="candidate" value="${index}"> <strong>${esc(row.targetTerm)}</strong> via ${esc(row.synonym)} → ${esc(row.kind.replaceAll("_"," "))} (${row.bridgeStrength})</label>`}).join("<br>")||"No candidates"}</fieldset>`).join("")}<button id="run-candidates" type="button">Search selected KJV words</button>`;$("#run-candidates").addEventListener("click",()=>{const selected=[...document.querySelectorAll('input[name="candidate"]:checked')].map(node=>bridges[Number(node.value)]).filter(Boolean);if(!selected.length){$("#topic-next").insertAdjacentHTML("afterbegin",'<div class="error-card">Select at least one KJV candidate word.</div>');return;}const rows=selected.flatMap(bridge=>exactWord(bridge.targetTerm,100).data.matches.map(match=>({...match,winningTerm:bridge.targetTerm})));$("#topic-next").innerHTML=`<div class="status-card">External bridges: ${esc(selected.map(row=>`${row.synonym} → ${row.targetTerm}`).join(", "))}. These paths are external evidence, not biblical definitions.</div><div class="section-title"><h3>${rows.length} exact-KJV results</h3><span>${esc([...new Set(selected.map(row=>row.targetTerm))].join(", "))}</span></div>${matchTable(rows)}`;});});}
function renderError(error){$("#result-title").textContent="Study error";$("#results").innerHTML=`<div class="error-card" role="alert"><strong>Could not complete the study.</strong><span>${esc(error.message||error)}</span></div>`;$("#live-status").textContent=`Search error: ${error.message||error}`;}

initialize();
